export type QueryConstraint =
  | { type: "where"; field: string; op: string; value: any }
  | { type: "orderBy"; field: string; dir: "asc" | "desc" }
  | { type: "limit"; n: number };

export type DocumentReference = { __ref: "doc"; path: string };
export type CollectionReference = { __ref: "col"; path: string };
export type Query =
  | CollectionReference
  | { __ref: "query"; base: CollectionReference; constraints: QueryConstraint[] };

export type FirebaseApp = { __demo: true };
export type Firestore = { __demo: true };
export type FirebaseStorage = { __demo: true };

const store: Record<string, Record<string, any>> = structuredClone(seed);
const listeners: Array<{ signature: string; cb: (snap: QuerySnapshot) => void }> = [];
let docCounter = 0;

export function collection(db: any, ...parts: any[]): CollectionReference {
  return { __ref: "col", path: joinPath(parts) };
}

export function doc(db: any, ...parts: any[]): DocumentReference {
  return { __ref: "doc", path: joinPath(parts) };
}

function joinPath(parts: any[]): string {
  const out: string[] = [];
  for (const part of parts) {
    if (part == null) continue;
    if (typeof part === "string") {
      const pieces = part.split("/").filter(Boolean);
      if (part.startsWith("/") && out.length === 0 && part.length > 1) {
        out.push(...pieces);
      } else if (part.includes("/")) {
        out.push(...pieces);
      } else {
        out.push(pieces[0]);
      }
    } else if (part && typeof part === "object" && "__ref" in part) {
      out.push(...(part as any).path.split("/").filter(Boolean));
    }
  }
  return out.join("/");
}

export function where(field: string, op: string, value: any): QueryConstraint {
  return { type: "where", field, op, value };
}

export function orderBy(field: string, dir: "asc" | "desc" = "asc"): QueryConstraint {
  return { type: "orderBy", field, dir };
}

export function limit(n: number): QueryConstraint {
  return { type: "limit", n };
}

export function query(base: CollectionReference, ...constraints: QueryConstraint[]): Query {
  if (constraints.length === 0) return base;
  return { __ref: "query", base, constraints };
}

export type DocumentSnapshot = {
  id: string;
  exists: boolean;
  data(): DocumentData;
};

export type QuerySnapshot = {
  docs: DocumentSnapshot[];
  size: number;
  empty: boolean;
  forEach(cb: (d: DocumentSnapshot) => void): void;
};

function matchesConstraints(data: DocumentData, constraints: QueryConstraint[]): boolean {
  for (const c of constraints) {
    if (c.type === "where") {
      const actual = data[c.field];
      const expected = c.value;
      if (actual === undefined) continue;
      switch (c.op) {
        case "==":
          if (actual !== expected) return false;
          break;
        case "!=":
          if (actual === expected) return false;
          break;
        case "array-contains":
          if (!Array.isArray(actual) || !actual.includes(expected)) return false;
          break;
        case "in":
          if (!Array.isArray(expected) || !expected.includes(actual)) return false;
          break;
        case ">":
          if (!(actual > expected)) return false;
          break;
        case ">=":
          if (!(actual >= expected)) return false;
          break;
        case "<":
          if (!(actual < expected)) return false;
          break;
        case "<=":
          if (!(actual <= expected)) return false;
          break;
        default:
          return false;
      }
    }
  }
  return true;
}

function makeSnapshot(data: Record<string, any>): QuerySnapshot {
  const docs = Object.entries(data).map(([id, value]) => ({
    id,
    exists: true,
    data: () => structuredClone(value),
  }));
  return {
    docs,
    size: docs.length,
    empty: docs.length === 0,
    forEach(cb) {
      docs.forEach(cb);
    },
  };
}

function emit(path: string): void {
  for (const l of listeners) {
    if (l.signature === path || path.startsWith(l.signature + "/") || l.signature.startsWith(path + "/")) {
      l.cb(makeSnapshot(store[l.signature] || {}));
    }
  }
}

export async function getDocs(q: Query): Promise<QuerySnapshot> {
  const { base, constraints } = q.__ref === "query" ? q : { base: q, constraints: [] as QueryConstraint[] };
  let data: Record<string, any> = {};
  const colPath = base.path;
  const raw = store[colPath] || {};
  for (const [id, value] of Object.entries(raw)) {
    if (matchesConstraints(value, constraints)) data[id] = value;
  }
  for (const c of constraints) {
    if (c.type === "orderBy") {
      const entries = Object.entries(data);
      entries.sort((a, b) => {
        const av = a[1][c.field];
        const bv = b[1][c.field];
        if (av === bv) return 0;
        const result = av > bv ? 1 : -1;
        return c.dir === "desc" ? -result : result;
      });
      data = Object.fromEntries(entries);
    }
    if (c.type === "limit") {
      data = Object.fromEntries(Object.entries(data).slice(0, c.n));
    }
  }
  return makeSnapshot(data);
}

export async function getDoc(ref: DocumentReference): Promise<DocumentSnapshot> {
  const parts = ref.path.split("/");
  const docId = parts[parts.length - 1];
  const colPath = parts.slice(0, -1).join("/");
  const value = store[colPath]?.[docId];
  return {
    id: docId,
    exists: !!value,
    data: () => structuredClone(value || {}),
  };
}

export async function setDoc(ref: DocumentReference, data: DocumentData, _opts?: any): Promise<void> {
  writeDoc(ref.path, structuredClone(data));
}

export async function addDoc(col: CollectionReference, data: DocumentData): Promise<DocumentReference> {
  const id = `doc_${++docCounter}`;
  writeDoc(`${col.path}/${id}`, structuredClone(data));
  return { __ref: "doc", path: `${col.path}/${id}` };
}

export async function updateDoc(ref: DocumentReference, partial: DocumentData): Promise<void> {
  const parts = ref.path.split("/");
  const docId = parts[parts.length - 1];
  const colPath = parts.slice(0, -1).join("/");
  const collection = store[colPath] || (store[colPath] = {});
  if (collection[docId]) {
    Object.assign(collection[docId], structuredClone(partial));
    emit(colPath);
  }
}

export async function deleteDoc(ref: DocumentReference): Promise<void> {
  const parts = ref.path.split("/");
  const docId = parts[parts.length - 1];
  const colPath = parts.slice(0, -1).join("/");
  if (store[colPath]) {
    delete store[colPath][docId];
    emit(colPath);
  }
}

function writeDoc(path: string, data: DocumentData): void {
  const parts = path.split("/");
  const docId = parts[parts.length - 1];
  const colPath = parts.slice(0, -1).join("/");
  store[colPath] = store[colPath] || {};
  store[colPath][docId] = data;
  emit(colPath);
}

export function onSnapshot(
  target: Query | DocumentReference,
  onNext: (snap: QuerySnapshot | DocumentSnapshot) => void,
  _onError?: (err: Error) => void
): () => void {
  const colPath = target.__ref === "doc" ? target.path.split("/").slice(0, -1).join("/") : target.path;
  let snapshot: any;
  if (target.__ref === "doc") {
    void getDoc(target).then((s) => onNext(s));
  } else {
    void getDocs(target).then((s) => {
      snapshot = s;
      onNext(s);
    });
  }
  const listener = { signature: colPath, cb: onNext };
  listeners.push(listener);
  return () => {
    const idx = listeners.indexOf(listener);
    if (idx >= 0) listeners.splice(idx, 1);
  };
}

export interface Transaction {
  get(ref: DocumentReference): Promise<DocumentSnapshot>;
  set(ref: DocumentReference, data: DocumentData): Transaction;
  update(ref: DocumentReference, partial: DocumentData): Transaction;
  delete(ref: DocumentReference): Transaction;
}

export async function runTransaction(
  _db: Firestore,
  fn: (tx: Transaction) => Promise<unknown>
): Promise<unknown> {
  const tx: Transaction = {
    async get(ref) {
      return getDoc(ref);
    },
    set(ref, data) {
      writeDoc(ref.path, structuredClone(data));
      return tx;
    },
    update(ref, partial) {
      const parts = ref.path.split("/");
      const docId = parts[parts.length - 1];
      const colPath = parts.slice(0, -1).join("/");
      if (store[colPath]?.[docId]) {
        Object.assign(store[colPath][docId], structuredClone(partial));
        emit(colPath);
      }
      return tx;
    },
    delete(ref) {
      const parts = ref.path.split("/");
      const docId = parts[parts.length - 1];
      const colPath = parts.slice(0, -1).join("/");
      if (store[colPath]) delete store[colPath][docId];
      emit(colPath);
      return tx;
    },
  };
  return fn(tx);
}

export interface WriteBatch {
  set(ref: DocumentReference, data: DocumentData): WriteBatch;
  update(ref: DocumentReference, partial: DocumentData): WriteBatch;
  delete(ref: DocumentReference): WriteBatch;
  commit(): Promise<void>;
}

export function writeBatch(_db: Firestore): WriteBatch {
  const ops: Array<() => void> = [];
  const batch: WriteBatch = {
    set(ref, data) {
      ops.push(() => writeDoc(ref.path, structuredClone(data)));
      return batch;
    },
    update(ref, partial) {
      ops.push(() => {
        const parts = ref.path.split("/");
        const docId = parts[parts.length - 1];
        const colPath = parts.slice(0, -1).join("/");
        if (store[colPath]?.[docId]) {
          Object.assign(store[colPath][docId], structuredClone(partial));
          emit(colPath);
        }
      });
      return batch;
    },
    delete(ref) {
      ops.push(() => {
        const parts = ref.path.split("/");
        const docId = parts[parts.length - 1];
        const colPath = parts.slice(0, -1).join("/");
        if (store[colPath]) delete store[colPath][docId];
        emit(colPath);
      });
      return batch;
    },
    async commit() {
      ops.forEach((op) => op());
    },
  };
  return batch;
}

